def preparar_jornadas_activas(apps, schema_editor):
    Jornada = apps.get_model('jornadas', 'JornadaRepartidor')
    consulta = Jornada.objects.using(schema_editor.connection.alias).filter(estado='ACTIVA').select_related('repartidor__empresa__pais')
    for jornada in consulta.iterator(chunk_size=200):
        nombre_zona = settings.TIME_ZONE
        if settings.MODO_APLICACION == 'CORPORATIVO' and jornada.repartidor.empresa_id:
            nombre_zona = jornada.repartidor.empresa.pais.zona_horaria_predeterminada
        zona = ZoneInfo(nombre_zona)
        fecha = jornada.iniciada_en.astimezone(zona).date()
        corte = max(jornada.iniciada_en, datetime.combine(fecha, time(22), tzinfo=zona))
        Jornada.objects.using(schema_editor.connection.alias).filter(pk=jornada.pk).update(fecha_operativa=fecha, cierre_programado_en=corte)


